-- SOURCE TWO QA DEMO | 2026-10-29 | 10 independent SELECTs, exactly 7 columns each.
-- Run ONE query at a time in Snowflake DEV; LIMIT 25 controls display only.
-- Exact deployed mapping/registry/hash version is NOT verified. A NULL OSCAL value
-- is NOT automatically a mapping failure; especially for Source Two SAP.
-- Catalog native title/version/remarks are members, not literal props[] entries.
-- Queries compare current RAW with persisted DIM; no Snowflake run performed.
-- Source evidence: Oscal-mapping-strategy simplify-metadata-boundary @ 9398f6de.

-- CATALOG SOURCE SOURCE_NAME
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'SOURCE_NAME' AS ARCHER_FIELD_NAME,GET(s.J,'SOURCE_NAME') AS ARCHER_VALUE,'title' AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,GET(d.METADATA_JSON,'title') AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_CATALOG_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AND d.ELEMENT_TYPE='metadata' ORDER BY s.CID LIMIT 25;

-- CATALOG SOURCE SOURCE_VERSION
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'SOURCE_VERSION' AS ARCHER_FIELD_NAME,GET(s.J,'SOURCE_VERSION') AS ARCHER_VALUE,'version' AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,GET(d.METADATA_JSON,'version') AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_CATALOG_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AND d.ELEMENT_TYPE='metadata' ORDER BY s.CID LIMIT 25;

-- CATALOG SOURCE SOURCE_DESCRIPTION
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'SOURCE_DESCRIPTION' AS ARCHER_FIELD_NAME,GET(s.J,'SOURCE_DESCRIPTION') AS ARCHER_VALUE,'remarks' AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,GET(d.METADATA_JSON,'remarks') AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_CATALOG_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AND d.ELEMENT_TYPE='metadata' ORDER BY s.CID LIMIT 25;

-- CATALOG SOURCE TRACKING ID (exact field+value identity)
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'SOURCE_TRACKING_ID' AS ARCHER_FIELD_NAME,GET(s.J,'SOURCE_TRACKING_ID') AS ARCHER_VALUE,d.METADATA_JSON:name::STRING AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,d.METADATA_JSON:value AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_CATALOG_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AND d.ELEMENT_TYPE='props' AND d.METADATA_JSON:name::STRING='tracking-id' AND d.PK_DIM_OSCAL_CATALOG_ELEMENT_HASH=MD5_BINARY('v1_registry_path_instance|ARCHER|ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW|'||s.CID||'|CATALOG|catalog.metadata.props[]|'||'SOURCE_TRACKING_ID:'||MD5('source-field-value-v1|SOURCE_TRACKING_ID|'||IFF(COALESCE(IS_NULL_VALUE(d.METADATA_JSON:value),FALSE),'None',d.METADATA_JSON:value::VARCHAR))) ORDER BY s.CID LIMIT 25;

-- CATALOG TOPIC RELATED_TO_KEY_CONTROLS, use embedded child Archer Content ID
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_TOPIC_RAW), g AS (SELECT id.VALUE:value::STRING AS TOPIC_ID,d.METADATA_JSON,d.ELEMENT_TYPE FROM RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_CATALOG_ELEMENT d,LATERAL FLATTEN(INPUT=>d.METADATA_JSON:props) id WHERE d.ELEMENT_TYPE='groups' AND id.VALUE:name::STRING='archer-content-id'), p AS (SELECT g.TOPIC_ID,g.ELEMENT_TYPE,f.VALUE:name::STRING AS PN,f.VALUE:value AS PV FROM g,LATERAL FLATTEN(INPUT=>g.METADATA_JSON:props) f WHERE f.VALUE:name::STRING='related-to-key-controls')
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_TOPIC_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'RELATED_TO_KEY_CONTROLS' AS ARCHER_FIELD_NAME,GET(s.J,'RELATED_TO_KEY_CONTROLS') AS ARCHER_VALUE,p.PN AS OSCAL_PROPERTY_NAME,p.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,p.PV AS OSCAL_VALUE FROM s LEFT JOIN p ON p.TOPIC_ID=s.CID AND GET(s.J,'RELATED_TO_KEY_CONTROLS') IS NOT NULL AND NOT COALESCE(IS_NULL_VALUE(GET(s.J,'RELATED_TO_KEY_CONTROLS')),FALSE) ORDER BY s.CID LIMIT 25;

-- ASSESSMENT RESULTS TOPIC COMPLIANCE_RATING (source-field instance identity)
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_TOPIC_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_TOPIC_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'COMPLIANCE_RATING' AS ARCHER_FIELD_NAME,GET(s.J,'COMPLIANCE_RATING') AS ARCHER_VALUE,d.METADATA_JSON:name::STRING AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,d.METADATA_JSON:value AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_ASSESSMENT_RESULTS_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_TOPIC_RAW' AND d.ELEMENT_TYPE='props' AND d.METADATA_JSON:name::STRING='compliance-rating' AND d.PK_DIM_OSCAL_ASSESSMENT_RESULTS_ELEMENT_HASH=MD5_BINARY('v1_registry_path_instance|ARCHER|ARCHER_CONTENT_AUTHORITATIVE_SOURCES_TOPIC_RAW|'||s.CID||'|ASSESSMENT_RESULTS|assessment-results.results[].props[]|'||'COMPLIANCE_RATING') ORDER BY s.CID LIMIT 25;

-- ASSESSMENT RESULTS SECTION COUNT_OF_NONCOMPLIANT_CONTROLS (source-field instance identity)
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'COUNT_OF_NONCOMPLIANT_CONTROLS' AS ARCHER_FIELD_NAME,GET(s.J,'COUNT_OF_NONCOMPLIANT_CONTROLS') AS ARCHER_VALUE,d.METADATA_JSON:name::STRING AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,d.METADATA_JSON:value AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_ASSESSMENT_RESULTS_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW' AND d.ELEMENT_TYPE='props' AND d.METADATA_JSON:name::STRING='noncompliant-count' AND d.PK_DIM_OSCAL_ASSESSMENT_RESULTS_ELEMENT_HASH=MD5_BINARY('v1_registry_path_instance|ARCHER|ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW|'||s.CID||'|ASSESSMENT_RESULTS|assessment-results.results[].props[]|'||'COUNT_OF_NONCOMPLIANT_CONTROLS') ORDER BY s.CID LIMIT 25;

-- ASSESSMENT PLAN SECTION COMPLIANCE_ENGAGEMENTS_SCOPE_PROCEDURES_FROM_SELECTED_AUTHORITATIVE_SOURCES: candidate props identity only; NULL target inconclusive
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'COMPLIANCE_ENGAGEMENTS_SCOPE_PROCEDURES_FROM_SELECTED_AUTHORITATIVE_SOURCES' AS ARCHER_FIELD_NAME,GET(s.J,'COMPLIANCE_ENGAGEMENTS_SCOPE_PROCEDURES_FROM_SELECTED_AUTHORITATIVE_SOURCES') AS ARCHER_VALUE,d.METADATA_JSON:name::STRING AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,d.METADATA_JSON:value AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_ASSESSMENT_PLAN_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW' AND d.ELEMENT_TYPE='props' AND d.PK_DIM_OSCAL_ASSESSMENT_PLAN_ELEMENT_HASH=MD5_BINARY('v1_registry_path_instance|ARCHER|ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SECTION_RAW|'||s.CID||'|SECURITY_ASSESSMENT_PLAN|assessment-plan.tasks[].props[]|'||'COMPLIANCE_ENGAGEMENTS_SCOPE_PROCEDURES_FROM_SELECTED_AUTHORITATIVE_SOURCES') ORDER BY s.CID LIMIT 25;

-- COMPONENT DEFINITION SOURCE POLICY_LEVEL_3: same property name, distinct exact field hash
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'POLICY_LEVEL_3' AS ARCHER_FIELD_NAME,GET(s.J,'POLICY_LEVEL_3') AS ARCHER_VALUE,d.METADATA_JSON:name::STRING AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,d.METADATA_JSON:value AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_COMPONENT_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AND d.ELEMENT_TYPE='props' AND d.METADATA_JSON:name::STRING='policy-level' AND d.PK_DIM_OSCAL_COMPONENT_ELEMENT_HASH=MD5_BINARY('v1_registry_path_instance|ARCHER|ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW|'||s.CID||'|COMPONENT_DEFINITION|component-definition.components[].props[]|'||'POLICY_LEVEL_3:'||MD5('source-field-value-v1|POLICY_LEVEL_3|'||IFF(COALESCE(IS_NULL_VALUE(d.METADATA_JSON:value),FALSE),'None',d.METADATA_JSON:value::VARCHAR))) ORDER BY s.CID LIMIT 25;

-- COMPONENT DEFINITION SOURCE POLICY_LEVEL_3_FROM_TOPIC_SECTION_AND_SUBSECTION_LEVELS: same property name, distinct exact field hash
WITH s AS (SELECT CONTENT_ID::VARCHAR AS CID,IFF(TYPEOF(CURATED_JSON)='VARCHAR',TRY_PARSE_JSON(AS_VARCHAR(CURATED_JSON)),CURATED_JSON) AS J FROM RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW)
SELECT 'RTX_RAW_DEV.ES_ESC_GRC.ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AS ARCHER_TABLE_NAME,s.CID AS CONTENT_ID,'POLICY_LEVEL_3_FROM_TOPIC_SECTION_AND_SUBSECTION_LEVELS' AS ARCHER_FIELD_NAME,GET(s.J,'POLICY_LEVEL_3_FROM_TOPIC_SECTION_AND_SUBSECTION_LEVELS') AS ARCHER_VALUE,d.METADATA_JSON:name::STRING AS OSCAL_PROPERTY_NAME,d.ELEMENT_TYPE AS OSCAL_ELEMENT_TYPE,d.METADATA_JSON:value AS OSCAL_VALUE FROM s LEFT JOIN RTX_ENTERPRISESERVICES_DEV.ES_ESC_GRC_CURATED.DIM_OSCAL_COMPONENT_ELEMENT d ON d.SOURCE_RECORD_ID=s.CID AND d.SOURCE_TABLE_NAME='ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW' AND d.ELEMENT_TYPE='props' AND d.METADATA_JSON:name::STRING='policy-level' AND d.PK_DIM_OSCAL_COMPONENT_ELEMENT_HASH=MD5_BINARY('v1_registry_path_instance|ARCHER|ARCHER_CONTENT_AUTHORITATIVE_SOURCES_SOURCE_RAW|'||s.CID||'|COMPONENT_DEFINITION|component-definition.components[].props[]|'||'POLICY_LEVEL_3_FROM_TOPIC_SECTION_AND_SUBSECTION_LEVELS:'||MD5('source-field-value-v1|POLICY_LEVEL_3_FROM_TOPIC_SECTION_AND_SUBSECTION_LEVELS|'||IFF(COALESCE(IS_NULL_VALUE(d.METADATA_JSON:value),FALSE),'None',d.METADATA_JSON:value::VARCHAR))) ORDER BY s.CID LIMIT 25;
